select hd.payment_req_number, hd.payment_req_date, contract.contract_id, hd.document_type as document_type,-- 单据 hd.company_id AS company_id, -- 公司id contract.contract_number as contract_number, -- 合同编号 contract.contract_name as contract_name, bp.bp_name as tenant_name , -- 承租人名称 cashflow.times as times, -- 期数--> item.description as yf_description, -- 应付项目 cashflow.due_amount as due_amount, -- 应付金额 ln.amount as amount, -- 本次申请金额 --> (ln.amount - nvl(ln.amount_paid,0)) as unpaid_amount, -- 剩余未支付金额 cashflow.due_date as due_date, -- 应付日期 ln.bp_id as bp_id, -- 付款对象 (select bp_name from hls_bp_master where bp_id=ln.bp_id ) as payment_Obj , -- 付款对象名称 ln.bp_bank_account_name as bp_bank_account_name, -- 对方账户名 ln.bp_bank_account_num as bp_bank_account_num, -- 对方银行账户号 ln.bp_bank_branch_name as bp_bank_branch_name, ln.bp_bank_account_id as bp_bank_account_id, ln.bp_bank_name as bp_bank_name, ln.self_bank_account_id, ln.self_bank_name, ln.self_bank_branch_name, ln.self_bank_account_num, ln.self_bank_account_name, ln.self_bank_account_id bank_account_id, ln.self_bank_account_num bank_account_num, ln.self_bank_account_name bank_account_name, ln.payment_flag as payment_flag, ln.payment_completed_date as payment_completed_date, ln.payment_method as payment_method, ( select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'CSH.PAYMENT_METHOD' and scvb.value = ln.payment_method ) as payment_method_desc, ln.description as description, nvl(ln.amount_paid,0) as amount_paid, ln.payment_req_ln_id as payment_req_ln_id, ln.payment_req_id as payment_req_id, ln.source_doc_line_id as source_doc_line_id, ln.source_doc_category as source_doc_category, cashflow.cf_item as cf_item , cashflow.cf_item as cf_type , cashflow.cashflow_id as cashflow_id, (select currency from csh_payment_req_hd where payment_req_id = ln.payment_req_id) as currency, contract.contract_id as source_doc_id from csh_payment_req_ln ln , csh_payment_req_hd hd, con_contract contract, con_contract_cashflow cashflow, hls_cashflow_item item ,hls_bp_master bp where hd.payment_req_id = ln.payment_req_id and ln.source_doc_id=contract.contract_id and cashflow.cf_item =0 and cashflow.contract_id=ln.source_doc_id and item.cf_item = cashflow.cf_item and bp.bp_id=contract.tenant_id and ln.source_doc_category = 'CON_CONTRACT' and ln.payment_req_ln_id IN
#{lnId}
UNION SELECT hd.payment_req_number, hd.payment_req_date, contract.contract_id, hd.document_type as document_type, hd.company_id AS company_id, withdraw.withdraw_number AS contract_number, contract.contract_name AS contract_name, ( SELECT bp_name FROM hls_bp_master WHERE bp_id = ln.bp_id ) AS tenant_name, -- 债权人名称 repayment.times AS times, -- 期数--> (SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = repayment.cf_type AND hci.cf_item = repayment.cf_item AND hci.enabled_flag = 'Y' )as yf_description, -- 应付项目 repayment.due_amount AS due_amount, -- 应付金额 ln.amount AS amount, -- 本次申请金额 --> (ln.amount - nvl(ln.amount_paid,0)) AS unpaid_amount, -- 剩余未支付金额 repayment.due_date AS due_date, -- 应付日期 ln.bp_id AS bp_id, -- 付款对象 ( SELECT bp_name FROM hls_bp_master WHERE bp_id = ln.bp_id ) AS payment_Obj, -- 承租人名称 ln.bp_bank_account_name AS bp_bank_account_name, -- 对方账户名 ln.bp_bank_account_num AS bp_bank_account_num, -- 对方银行账户号 ln.bp_bank_branch_name AS bp_bank_branch_name, ln.bp_bank_account_id AS bp_bank_account_id, ln.bp_bank_name AS bp_bank_name, ln.self_bank_account_id, ln.self_bank_name, ln.self_bank_branch_name, ln.self_bank_account_num, ln.self_bank_account_name, ln.self_bank_account_id bank_account_id, ln.self_bank_account_num bank_account_num, ln.self_bank_account_name bank_account_name, ln.payment_flag AS payment_flag, ln.payment_completed_date AS payment_completed_date, ln.payment_method AS payment_method, ( select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'CSH.PAYMENT_METHOD' and scvb.value = ln.payment_method ) as payment_method_desc, ln.description AS description, nvl(ln.amount_paid,0) AS amount_paid, ln.payment_req_ln_id AS payment_req_ln_id, ln.payment_req_id AS payment_req_id, ln.source_doc_line_id AS source_doc_line_id, ln.source_doc_category AS source_doc_category, repayment.cf_item AS cf_item, repayment.cf_type AS cf_type, repayment.repayment_id AS cashflow_id, ( SELECT currency FROM csh_payment_req_hd WHERE payment_req_id = ln.payment_req_id ) AS currency, ln.source_doc_id AS source_doc_id FROM csh_payment_req_ln ln, csh_payment_req_hd hd, lon_contract contract, lon_contract_repayment repayment, lon_contract_withdraw withdraw WHERE hd.payment_req_id = ln.payment_req_id AND ln.source_doc_id = withdraw.withdraw_id and ln.source_doc_line_id = repayment.repayment_id and contract.contract_id = withdraw.contract_id and contract.contract_id = repayment.contract_id and ln.source_doc_category = 'LON_CONTRACT_WITHDRAW' and ln.payment_req_ln_id IN
#{lnId}
UNION SELECT hd.payment_req_number, hd.payment_req_date, contract.contract_id, hd.document_type as document_type, hd.company_id AS company_id, contract.contract_number AS contract_number, contract.contract_name AS contract_name, ( SELECT bp_name FROM hls_bp_master WHERE bp_id = ln.bp_id ) AS tenant_name,
fqc.times AS times,
(SELECT description FROM hls_cashflow_item hci WHERE hci.cf_type = fqc.cf_type AND hci.cf_item = fqc.cf_item AND hci.enabled_flag = 'Y' )as yf_description, fqc.due_amount AS due_amount, ln.amount AS amount, (ln.amount - nvl(ln.amount_paid,0)) AS unpaid_amount, fqc.due_date AS due_date, ln.bp_id AS bp_id, ( SELECT bp_name FROM hls_bp_master WHERE bp_id = ln.bp_id ) AS payment_Obj, -- 承租人名称 ln.bp_bank_account_name AS bp_bank_account_name, -- 对方账户名 ln.bp_bank_account_num AS bp_bank_account_num, -- 对方银行账户号 ln.bp_bank_branch_name AS bp_bank_branch_name, ln.bp_bank_account_id AS bp_bank_account_id, ln.bp_bank_name AS bp_bank_name, ln.self_bank_account_id, ln.self_bank_name, ln.self_bank_branch_name, ln.self_bank_account_num, ln.self_bank_account_name, ln.self_bank_account_id bank_account_id, ln.self_bank_account_num bank_account_num, ln.self_bank_account_name bank_account_name, ln.payment_flag AS payment_flag, ln.payment_completed_date AS payment_completed_date, ln.payment_method AS payment_method, ( select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'CSH.PAYMENT_METHOD' and scvb.value = ln.payment_method ) as payment_method_desc, ln.description AS description, nvl(ln.amount_paid,0) AS amount_paid, ln.payment_req_ln_id AS payment_req_ln_id, ln.payment_req_id AS payment_req_id, ln.source_doc_line_id AS source_doc_line_id, ln.source_doc_category AS source_doc_category, fqc.cf_item AS cf_item, fqc.cf_type AS cf_type, fqc.quotation_cashflow_id AS cashflow_id, ( SELECT currency FROM csh_payment_req_hd WHERE payment_req_id = ln.payment_req_id ) AS currency, ln.source_doc_id as source_doc_id FROM csh_payment_req_ln ln, csh_payment_req_hd hd, fct_contract contract, fct_quotation_cashflow fqc WHERE hd.payment_req_id = ln.payment_req_id AND ln.source_doc_id = contract.contract_id and ln.source_doc_line_id = fqc.quotation_cashflow_id and ln.source_doc_category = 'FCT_CONTRACT' and ln.payment_req_ln_id IN
#{ln_id}

mapper.update:
update csh_payment_req_ln cpr
set
cpr.payment_flag = #{paymentFlag,jdbcType=VARCHAR}
where
cpr.payment_req_ln_id = #{paymentReqLnId,jdbcType=BIGINT}

update csh_payment_req_ln cpr

    cpr.amount_paid =#{amountPaid}

        ,cpr.payment_flag = #{paymentFlag}


where
cpr.payment_req_ln_id = #{paymentReqLnId}

mapper.select:
select t.*, (t.amount - t.deduction_amount) as applied_pay_amount from ( select ln.payment_req_ln_id, ln.payment_req_id, ln.source_doc_category, ln.source_doc_id, ln.source_doc_id contract_id, ln.source_doc_line_id, ln.amount, ln.amount_paid, ln.payment_flag, ln.payment_completed_date, ln.payment_method, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = ln.payment_method ) payment_method_n, (select TENANT_ID from PRJ_PROJECT where PROJECT_ID = (SELECT DOCUMENT_ID from prj_quotation WHERE QUOTATION_ID = pq.QUOTATION_ID)) bp_id, ln.bp_bank_account_id, ln.bp_bank_name, ln.bp_bank_branch_name, ln.bp_bank_account_num, ln.bp_bank_account_name, ln.return_account, ln.object_version_number, ln.request_id, ln.program_id, ln.created_by, ln.creation_date, ln.last_updated_by, ln.last_update_date, ln.last_update_login, ln.self_bank_account_id, ln.self_bank_name, ln.self_bank_branch_name, ln.self_bank_account_num, ln.self_bank_account_name, ln.fund_source, ln.funding_plan_ln_id, ln.deduct_amount, ln.if_from_contract, ln.exchange, ln.bp_type, ln.eas_code, ln.bill_type, ln.due_amount_ln, ln.seq_num, ln.sum_due_amount, ln.acceptance_period, ln.validity_lc, ln.iban, ln.swift, ln.beneficiary, ln.purchase_contract_id, ln.purchase_contract_amount, ln.purchase_contract_amount_sum, ln.purchase_contract_balance, ln.contract_balance_release, ln.bill_id, ln.bank_address, ln.current_applied_amount, hd.payment_req_number, hd.payment_req_date, hd.apply_pay_date, hd.description, hd.payment_req_status, hd.process_instance_id,
(select cc.project_id from con_contract cc where cc.contract_id = ln.source_doc_id) project_id, (select cc.contract_number from con_contract cc where cc.contract_id = ln.source_doc_id) contract_number, (select cc.contract_name from con_contract cc where cc.contract_id = ln.source_doc_id) contract_name, (select cc.LEASE_CHANNEL from con_contract cc where cc.contract_id = ln.source_doc_id) lease_channel, (select cc.business_type from con_contract cc where cc.contract_id = ln.source_doc_id) business_type, (select bp.bp_code from hls_bp_master bp where bp.bp_id = ln.bp_id) bp_code, (select bp.bp_name from hls_bp_master bp where bp.bp_id = (select TENANT_ID from PRJ_PROJECT where PROJECT_ID = (SELECT DOCUMENT_ID from prj_quotation WHERE QUOTATION_ID = pq.QUOTATION_ID))) bp_name, (select cc.currency from con_contract cc where cc.contract_id = ln.source_doc_id) currency, (select fc.currency_name from con_contract cc, fnd_currency fc where cc.contract_id = ln.source_doc_id and fc.currency_code = cc.currency) currency_n, nvl((select sum(nvl(dt.deduct_amount, 0)) from csh_payment_req_dt dt where dt.payment_req_ln_id = ln.payment_req_ln_id), 0) deduction_amount, (ln.amount - nvl(ln.amount_paid, 0) - nvl((select sum(nvl(dt.deduct_amount, 0)) from csh_payment_req_dt dt where dt.payment_req_ln_id = ln.payment_req_ln_id and dt.deduct_flag = 'N'), 0)) as can_deduction_amount, nvl(ccc.received_amount, 0) received_amount, (ccc.due_amount - nvl(ccc.received_amount, 0)) surplus_amount, ccc.cf_item, (select i.description from con_contract_cashflow ccc, hls_cashflow_item i where ccc.cashflow_id = ln.source_doc_line_id and i.cf_item = ccc.cf_item and ccc.cf_type = i.cf_type) cf_item_n, ccc.cf_type, (select ccc.times from con_contract_cashflow ccc where ccc.cashflow_id = ln.source_doc_line_id) times, pq.QUOTATION_ID, pq.QUOTATION_NUMBER, ccc.DUE_AMOUNT due_amount,
(select nvl(sum(nvl(ccc.DUE_AMOUNT, 0)), 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CONTRACT_ID = ln.source_doc_id AND ccc.cf_item = 51 AND ccc.CF_TYPE = 5) as deposit_due_amount, (select nvl(sum(nvl(ccc.RECEIVED_AMOUNT, 0)), 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CONTRACT_ID = ln.source_doc_id AND ccc.cf_item = 51 AND ccc.CF_TYPE = 5) as deposit_received_amount, (select nvl(sum(nvl(ccc.DUE_AMOUNT, 0)), 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CONTRACT_ID = ln.source_doc_id AND ccc.cf_item = 65 AND ccc.CF_TYPE = 65) as service_charge_due_amount, (select nvl(sum(nvl(ccc.RECEIVED_AMOUNT, 0)), 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CONTRACT_ID = ln.source_doc_id AND ccc.cf_item = 65 AND ccc.CF_TYPE = 65) as service_charge_received_amount, (select nvl(sum(nvl(ccc.DUE_AMOUNT, 0)), 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CONTRACT_ID = ln.source_doc_id AND ccc.cf_item = 66 AND ccc.CF_TYPE = 65) as service_fee_due_amount, (select nvl(sum(nvl(ccc.RECEIVED_AMOUNT, 0)), 0) from CON_CONTRACT_CASHFLOW ccc where ccc.CONTRACT_ID = ln.source_doc_id AND ccc.cf_item = 66 AND ccc.CF_TYPE = 65) as service_fee_received_amount
from csh_payment_req_hd hd, csh_payment_req_ln ln left join CON_CONTRACT_CASHFLOW ccc on ccc.CASHFLOW_ID = ln.SOURCE_DOC_LINE_ID left join prj_quotation pq on pq.quotation_id = ccc.GENERATED_SOURCE_DOC_ID where hd.payment_req_id = ln.payment_req_id) t
and t.payment_req_id = #{paymentReqId}
and t.process_instance_id = #{processInstanceId}
and t.payment_req_ln_id = #{paymentReqLnId}
and ( ('Y' = #{reverseFlag} AND ifnull(t.submit_flag,'N') = 'Y') OR ('N' = #{reverseFlag}) )
